;--------------------------------------------------------------------; нОХЯЮМХЕ: аЕЦСЫЮЪ ЯРПНЙЮ; юБРНП ОНПРЮ: рЮПЮЯНБ л.м.(Mick),2016;--------------------------------------------------------------------Str_reload:		ld	a,(Str_flg_end)		and	a		jr 	z,Str_init		xor	a		ld	(Str_flg_end),a		scf		retStr_init:		ld	hl,Str_addr_text		ld	(Str_addr_work),hl		retStr_init_load:		ld	hl,Str_addr_load		ld	(Str_addr_work),hl		ld	a,1		ld	(Str_flg_end),a		ld	a,(hl)		ret	Str_play:		ld	a,(Str_count_bit)		or	a		call	z,Str_next_symol		retStr_next_symol:		ld	hl,(Str_addr_work)		ld	a,(hl)		and	a		jr	z,Str_reload		ret	c		inc	hl		ld	(Str_addr_work),hl		sub	20h		cp	60h		jr	c, Str_load_data		sub	60hStr_load_data:		ld	l, a		ld	h, 0		ld	de,Str_addr_font		add	hl,hl		add	hl,hl		add	hl,hl		add	hl,de		ld	de,Str_symbol_buf		ldi			ldi			ldi			ldi			ldi			ldi			ldi			ldi			ld	a,8		ld	(Str_count_bit),a		ret	Str_update_symbol:		ld	de, Str_symbol_buf		ld	b,8		ld	hl, 40F5hloc_0_9BA8:		ld	c,0		ld	a,(de)		rlca		ld	(de),a		jr	nc,loc_0_9C03		inc	c		loc_0_9C03:		ld	a,0FEh		and	(hl)		or	c		ld	(hl),a		inc	h		ld	a,h		and	7		jr	nz,loc_0_9BC2		ld	a,l		add	a,20h		ld	l,a		jr	c,loc_0_9BC2		ld	a,h		sub	8		ld	h,aloc_0_9BC2:		inc	de		djnz	loc_0_9BA8		ld	a,(Str_count_bit)		dec	a		ld	(Str_count_bit),a		retStr_draw_symbol:		ld	hl,40F5h		ld	b,8Str_draw_line:		push	hl		and	a		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		pop	hl		inc	h		ld	a,h		and	7		jr	nz,Str_next_line		ld	a,l		add	a,20h		ld	l,a		ld	c,a		jr	c,Str_next_line		ld	a,h		sub	8		ld	h,aStr_next_line:		djnz	Str_draw_line		ret	Str_symbol_buf:		db 	0,0,0,0,0,0,0,0Str_flg_end:		db 	0Str_count_bit:		db 	0Str_addr_work:		dw 	0Str_addr_load:		db	'  *LOAD*  ',0Str_addr_text:		db 	'                << SPACE TO CHANGE MUSIC >>       '		db 	'                опхбер, опхбер! MICK ькер бюл окюлеммши опхбер !'		db	' яеи бшосяй опхспнвем й опедярнъыеи бшярюбйе-теярхбюкч CHAOS CONSTRUCTION 2016, йнрнпюъ мювмеряъ асйбюкэмн гюбрпю'		db	' 27 юбцсярю. сбш б щрнр пюг ъ ме ялнцс ее оняерхрэ он тхмюмянбшл яннапюфемхъл, онщрнлс онйпхрхйнбюрэ'		db	' х онбнпвюрэ ме сдюярэяъ он онбндс дсьмнцн вепдюйю-йспърмхйю, цде опнундхкн лепнопхърхе б опнькнл цндс.'		db	' бхдхлн мюпндс онмпюбхкняэ бгахпюрэяъ мю яеи вепдюй он сгйни кеямйе, врн пеьхкх б щрнл цндс онбрнпхрэ.'		db	' юу, б щрнл цндс лме ме опхдеяръ йюпюайюрэяъ, ю фюкэ. мс дю кюдмн, лнфер б якедсчыел цндс бшаепсяэ.'		db	' ю онйюопн яанпмхй дкъ йюпрнвйх ZXM-MOONSOUND. ноърэ йюпрхмйс онднцмюк AAA, ъ ее рнкэйн мелмнцн онопюбхк рюл цде'		db	' бнгмхйкю б щрнл менаундхлнярэ. ноърэ фе AAA пюяяйюгюк врн х йсдю мюдн пюглеярхрэ. х дю, нм пеьхк, рюй яйюгюрэ'		db	' йюомсрэ 40 цпюдсямнцн аюкэгюлвхйю мю дсьс RINDEX, лнк осярэ ьпхтр асдер DIZZY. мс кюдмн ъ пеьхк, веи рн'		db	' ме бшохрэ, тс рш - йюомсрэ рн мю дсьс :) йнпнве рсрю DIZZY ьпхтр. рнкэйн бнр гюяюдю, нм б меонмърмни ашк'		db	' йндхпнбйх, опхькняэ йнмбепрхрэ. AAA, йюйни бей мю дбнпе - яеивюя лндмн кхан б 866, кхан б 1251 йндхпнбйе декюрэ.'		db	' ю рн б якедсчыхи пюг яюл охьх рейяр дкъ аецсыеи ярпнйх. тсссс, ъ сфе опхрнлхкяъ хгбкейюрэ хг ябнеи окчьебни цнкнбш'		db	' бяъйхе асйбш х якнбю, онфюкси убюрхр мю щрнл.'    		db	' хрюй, б щрнл яанпмхйе дебърмюджюрэ лекндхи, йнрнпше'		db	' оепейкчвючряъ осрел мюфюрхъ йкюбхьх "SPACE", кхан фдере онйю ме гюйнмвхряъ лекндхъ.'		db	' яохянй лекндхи хдер якеднл: '		db	' BONE.MWM (GIVE THA DOG A BONE - MEITS 1995),'		db	' CLODHOPP.MWM (ONE HELL OF AN INTRO - MEITS 1995),'		db	' DRAAIKOE.MWM (DRAAIKOEKOEKSWLS - VALENCIA, ALLERHANDLE .F.J.W.KOLLER),'		db	' FEED.MWM (GIVE ME MY FEED BACK!! - MEITS 1995),'		db	' FRIK.MWM (FRIKANDEL SPECIAL - MEITS 1995),'		db	' GRAGA.MWM (GRADIUS GAIDEN! - KONAMI MAN 1997),'		db	' HAPPYJOY.MWM (HAPPY, HAPPY, JOY, JOY... - 